ee:message.ee:set-payload:
%dw 2.0
output application/json
import mergeWith from dw::core::Objects
---
payload mergeWith {
    status:    vars.failureStatus,
    error:     error.description default "unknown error",
    updatedAt: (now() >> |+00:00|) as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
import mergeWith from dw::core::Objects
---
payload mergeWith {
    status:    vars.targetStatus,
    updatedAt: (now() >> |+00:00|) as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}
